+        TemporalAccessor from,
+        TemporalAccessor to,
+        @Nullable DateHistogramInterval step,
+        @Nullable Map<String, Object> afterKey,
+        @Nullable Map<String, Object> previousTimeSeries,
+        MetricsCallback callback
