+            .addGroup(IndexPrivilege.ALL, FieldPermissions.DEFAULT, null, true, "*")
+            .addGroup(IndexPrivilege.NONE, fieldPermissions, queries, randomBoolean(), "*")
+            .build();
+        assertThat(indicesPermission3.hasFieldOrDocumentLevelSecurity(), is(false));
